trial.program_source:
def transform(grid):
    pts={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: pts.setdefault(v,[]).append((r,c))
    if not pts:return [row[:] for row in grid]
    color=min(pts,key=lambda v:min(pts[v]))
    p=pts[color]
    a=min(r for r,c in p);b=max(r for r,c in p)
    x=min(c for r,c in p);y=max(c for r,c in p)
    return [[color if grid[r][c]==color else 0 for c in range(x,y+1)] for r in range(a,b+1)]

